using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "EngineAssaultCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Hevelius/EngineAssaultCustomDescription", order = 0)]
public class EngineAssaultCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		EngineAssaultAction engineAssaultAction = battleAction as EngineAssaultAction;
		return Smart.Format(base.localizationManager.GetLocalizedWhereX(engineAssaultAction.PurifyCorruptAction.GetActionDescription(-1).RemoveLast(), y: false, Smart.Format(GetRawLocalizedDescription(battleAction), amountModified)));
	}
}
